{
  "subtype": "predictive_feature_engineering",
  "focus_variable": "urgency",
  "per_column": [
    {
      "name": "urgency_signal_count",
      "role": "leakage",
      "is_predictor": false,
      "rationale": "A count of 'urgency signals' is constructed by directly enumerating cues of the focus concept itself. It is a restatement/aggregation of urgency indicators rather than an independent predictor, so it effectively encodes the label and leaks the outcome."
    },
    {
      "name": "has_critical_keywords",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "A binary flag for critical keywords extracted from the free-text reason_for_visit is a legitimate feature derived from the note content. It lies outside the urgency label, is knowable at intake, and plausibly carries predictive signal about urgency without being a deterministic restatement of it."
    },
    {
      "name": "has_acute_presentation",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Acute presentation is a clinical characteristic drawn from the note that is distinct from the urgency assignment and plausibly correlates with it. It is a valid intake-time predictor rather than a direct component of the focus variable."
    },
    {
      "name": "has_severe_symptoms",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Severity of symptoms is an independent, note-derived clinical signal available before any urgency determination and carries genuine predictive information about urgency without simply restating the label."
    }
  ],
  "n_predictors": 3,
  "predictive_utility": 0.5,
  "rationale": "Three of the four columns (critical keywords, acute presentation, severe symptoms) are legitimate note-derived predictors that are distinct from the urgency label yet plausibly correlated with it, giving real predictive leverage. However, urgency_signal_count is essentially a tally of urgency cues and effectively restates/leaks the focus. The set has moderate genuine utility, tempered by overlap among the severity flags and one leaking column."
}

